    return row('not-evidence', `no proposal: the run ${b?.run?.shipped ? 'shipped' : 'did not ship'} and its review is ${b?.review?.close ? 'closed' : b?.review ? 'open' : 'absent'}; only a closed review's proposal is completion evidence`);
  }
